"""Export runtime dependencies from pyproject.toml to requirements.txt (Streamlit Cloud).

Usage: python scripts/export_requirements.py [--check]
"""

from __future__ import annotations

import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render() -> str:
    """requirements.txt content: pinned runtime deps + the AI extra + the package itself."""
    project = tomllib.loads((ROOT / "pyproject.toml").read_text())["project"]
    deps = project["dependencies"] + project["optional-dependencies"]["ai"]
    lines = [
        "# Generated by scripts/export_requirements.py from pyproject.toml - do not edit.",
        *deps,
        "# install the PulseIQ package itself (src/ layout)",
        "-e .",
    ]
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    text = render()
    target = ROOT / "requirements.txt"
    if "--check" in sys.argv:
        ok = target.exists() and target.read_text() == text
        print("requirements.txt is up to date" if ok else "requirements.txt is stale - run make requirements")
        sys.exit(0 if ok else 1)
    target.write_text(text)
    print(f"wrote {target}")
